INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter Beleuchtung im Arbeitskontext?', 2, '[{"text": "Lichtverhältnisse am Arbeitsplatz", "correct": true, "because": "Beeinflusst Ergonomie"}, {"text": "Softwarebeleuchtung", "correct": false, "because": "Kein Konzept"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Beleuchtung als Fachinformatiker?', 3, '[{"text": "Gesundheit und Produktivität fördern", "correct": true, "because": "Ergonomische Arbeitsbedingungen"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Systemleistung steigern", "correct": false, "because": "Kein technischer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorschriften regeln die Beleuchtung am Arbeitsplatz?', 5, '[{"text": "Arbeitsstättenverordnung (ArbStättV)", "correct": true, "because": "§ 7 regelt Beleuchtung"}, {"text": "DIN EN 12464-1", "correct": true, "because": "Norm für Beleuchtung"}, {"text": "Mindestlohngesetz", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Beleuchtung muss blendfrei sein. b) Sie ist nur für Büros relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Arbeitsplätze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung der Beleuchtung?', 4, '[{"text": "Lichtstärke", "correct": false, "because": "Entscheidend für Ergonomie"}, {"text": "Blendungsschutz", "correct": false, "because": "Schützt Augen"}, {"text": "Büroverschönerung", "correct": true, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Beleuchtung die Bildschirmarbeit beeinflusst?', 2, '[{"text": "Ja", "correct": true, "because": "Blendung kann stören"}, {"text": "Nein", "correct": false, "because": "Ergonomisch relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beleuchtungsart ist für Bildschirmarbeitsplätze empfohlen?', 3, '[{"text": "Indirekte Beleuchtung", "correct": true, "because": "Reduziert Reflexionen"}, {"text": "Spotlights", "correct": false, "because": "Blendungsrisiko"}, {"text": "Kerzenlicht", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Beleuchtungsplanung eines Fachinformatikers?', 5, '[{"text": "Lichtstärke (Lux)", "correct": true, "because": "Normgerechte Helligkeit"}, {"text": "Farbwiedergabe", "correct": true, "because": "Natürliches Licht"}, {"text": "Marketingstrategie", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Beleuchtung muss den Normen entsprechen. b) Sie ist nur für Sehbehinderte wichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Beleuchtung unwichtig?', 4, '[{"text": "Kontrastverhältnisse", "correct": false, "because": "Für Sicht wichtig"}, {"text": "Lichtrichtung", "correct": false, "because": "Blendung vermeiden"}, {"text": "Farbe der Lampenverkleidung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss die Beleuchtung gemäß ArbStättV geprüft werden?', 2, '[{"text": "Ja", "correct": true, "because": "Regelmäßige Prüfung nötig"}, {"text": "Nein", "correct": false, "because": "Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet gute Beleuchtung für Fachinformatiker?', 4, '[{"text": "Weniger Augenbelastung", "correct": true, "because": "Schützt Gesundheit"}, {"text": "Höhere Produktivität", "correct": true, "because": "Bessere Arbeitsbedingungen"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Beleuchtung nur Tageslicht sein muss. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kombination mit Kunstlicht"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Beleuchtung?', 3, '[{"text": "Ergonomie", "correct": true, "because": "Schützt Gesundheit"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Beleuchtung muss blendfrei sein. b) Sie ist nur für Bildschirmarbeitsplätze relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Arbeitsplätze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat schlechte Beleuchtung?', 5, '[{"text": "Augenbelastung", "correct": true, "because": "Gesundheitsrisiko"}, {"text": "Geringere Produktivität", "correct": true, "because": "Schlechte Sicht"}, {"text": "Schnellere Arbeit", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei der Beleuchtung?', 3, '[{"text": "Ergonomische Planung", "correct": true, "because": "Arbeitsplatzgestaltung"}, {"text": "Softwareentwicklung", "correct": false, "because": "Kein direkter Bezug"}, {"text": "Marketing", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Beleuchtung die Gesundheit beeinflussen?', 2, '[{"text": "Ja", "correct": true, "because": "Augen und Wohlbefinden"}, {"text": "Nein", "correct": false, "because": "Nachweisbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Norm wähle ich für die Beleuchtung?', 4, '[{"text": "DIN EN 12464-1", "correct": true, "because": "Beleuchtungsstandard"}, {"text": "ISO 9001", "correct": false, "because": "Qualitätsmanagement"}, {"text": "HTML5", "correct": false, "because": "Kein Bezug"}]');
